alter table public.vehicles add column if not exists wheelchair_accessible boolean not null default false,add column if not exists renavam text,add column if not exists insurance_expiry date,add column if not exists licensing_expiry date,add column if not exists updated_at timestamptz not null default now();
alter table public.maintenances add column if not exists parts_value numeric,add column if not exists labor_value numeric,add column if not exists updated_at timestamptz not null default now();
create index if not exists vehicles_municipality_status_idx on public.vehicles(municipality_id,status);create index if not exists maintenances_vehicle_status_idx on public.maintenances(vehicle_id,status);create index if not exists maintenances_next_date_idx on public.maintenances(municipality_id,next_maintenance_date);create index if not exists fuelings_vehicle_date_idx on public.fuelings(vehicle_id,date desc);
create or replace function private.sync_vehicle_from_maintenance() returns trigger language plpgsql security definer set search_path='' as $$begin if new.status='IN_PROGRESS' then update public.vehicles set status='MAINTENANCE',updated_at=now() where id=new.vehicle_id and status<>'IN_USE';elsif new.status in ('COMPLETED','CANCELLED') and old.status='IN_PROGRESS' then update public.vehicles set status='AVAILABLE',updated_at=now() where id=new.vehicle_id and status='MAINTENANCE';end if;return new;end;$$;revoke all on function private.sync_vehicle_from_maintenance() from public;grant execute on function private.sync_vehicle_from_maintenance() to authenticated;drop trigger if exists maintenances_sync_vehicle on public.maintenances;create trigger maintenances_sync_vehicle after insert or update of status on public.maintenances for each row execute function private.sync_vehicle_from_maintenance();
create or replace function private.sync_vehicle_from_fueling() returns trigger language plpgsql security definer set search_path='' as $$begin if new.mileage is not null then update public.vehicles set current_mileage=greatest(current_mileage,new.mileage),updated_at=now() where id=new.vehicle_id;end if;return new;end;$$;revoke all on function private.sync_vehicle_from_fueling() from public;grant execute on function private.sync_vehicle_from_fueling() to authenticated;drop trigger if exists fuelings_sync_vehicle on public.fuelings;create trigger fuelings_sync_vehicle after insert or update of mileage on public.fuelings for each row execute function private.sync_vehicle_from_fueling();